export interface Authenticator {
  authenticate(request: Request): Promise<Principal | null>;
}

const registry: Record<string, Authenticator> = {
  password: passwordAuthenticator(users),
  bearer: bearerAuthenticator(jwks, issuer),
};

export async function login(scheme: string, request: Request): Promise<Principal | null> {
  const authenticator = registry[scheme];
  if (!authenticator) throw new UnknownSchemeError(scheme);
  return authenticator.authenticate(request);      // null = invalid credentials
}
